<?php

declare(strict_types=1);

namespace Database\Seeders;

use App\Modules\Library\Infrastructure\Persistence\Models\LibraryArticle;
use App\Modules\Library\Infrastructure\Persistence\Models\LibraryCategory;
use Illuminate\Database\Seeder;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Schema;

final class LibraryArtifactUpgradeSeeder extends Seeder
{
    public function run(): void
    {
        DB::transaction(function (): void {
            if (LibraryArticle::withTrashed()->where('slug', 'zatochka-artefaktov')->exists()) {
                $this->command?->info('Статья уже существует; содержимое сохранено.');

                return;
            }
            $category = LibraryCategory::query()->where('slug', 'artefakty')->firstOrFail();
            $article = new LibraryArticle;
            $article->fill([
                'category_id' => $category->id,
                'slug' => 'zatochka-artefaktov',
                'title' => ['ru' => 'Заточка артефактов', 'uk' => 'Заточування артефактів'],
                'excerpt' => [
                    'ru' => 'Как усилить артефакт в кузне: копия +0, дополнительные материалы, монеты и гарантированное улучшение.',
                    'uk' => 'Як посилити артефакт у кузні: копія +0, додаткові матеріали, монети та гарантоване покращення.',
                ],
                'content' => ['ru' => $this->content('ru'), 'uk' => $this->content('uk')],
                'status' => LibraryArticle::STATUS_PUBLISHED,
                'published_at' => now(),
                'sort_order' => (int) $category->articles()->max('sort_order') + 10,
            ]);
            foreach (['title', 'excerpt', 'content'] as $field) {
                if (Schema::hasColumn('library_articles', $field.'_legacy')) {
                    $article->setAttribute($field.'_legacy', $article->getTranslation($field, 'ru'));
                }
            }
            $article->save();
            $this->command?->info('Создана статья «Заточка артефактов», ID: '.$article->id);
        });
    }

    private function content(string $locale): string
    {
        $uk = $locale === 'uk';
        $intro = $uk
            ? '<p>Знайомий артефакт може стати сильнішим. У кузні ви можете підвищувати його заточування, поступово посилюючи власні характеристики реліквії. Кожен ступінь має <b>100% успіху</b>: випадкового провалу та знищення артефакту немає.</p>'
            : '<p>Знакомый артефакт может стать сильнее. В кузне вы можете повышать его заточку, постепенно усиливая собственные характеристики реликвии. Каждая ступень имеет <b>100% успеха</b>: случайного провала и уничтожения артефакта нет.</p>';

        $where = $uk
            ? '<p>Прийдіть до кузні та відкрийте <b>«Крафт» → «Заточування артефактів»</b> у бічному меню. На сторінці показано доступні артефакти з рюкзака, необхідні компоненти, ціну та зміни характеристик.</p><p>У списку є лише артефакти, для яких доступне заточування. Одягнений артефакт потрібно спочатку зняти в рюкзак.</p>'
            : '<p>Придите в кузню и откройте <b>«Крафт» → «Заточка артефактов»</b> в боковом меню. На странице показаны доступные артефакты из рюкзака, необходимые компоненты, цена и изменения характеристик.</p><p>В списке есть только артефакты, для которых доступна заточка. Надетый артефакт нужно сначала снять в рюкзак.</p>';
        $resources = $uk
            ? '<ul><li><b>Артефакт для покращення</b> — з поточним рівнем заточування.</li><li><b>Одна копія цього самого артефакту +0</b> — витрачається на покращення. Інший артефакт тієї самої рідкості не підходить.</li><li><b>Додаткові матеріали</b> — якщо вони потрібні для вибраного артефакту; склад і кількість показано в кузні.</li><li><b>Монети</b> — сума вказана біля кнопки заточування.</li></ul><p>Для одного виду артефакту <b>ціна та кількість додаткових матеріалів однакові на кожному ступені</b>. Наприклад, перехід із +0 на +1 і з +12 на +13 коштує однаково. Для різних артефактів умови можуть відрізнятися.</p>'
            : '<ul><li><b>Улучшаемый артефакт</b> — с текущим уровнем заточки.</li><li><b>Одна копия этого же артефакта +0</b> — расходуется на улучшение. Другой артефакт той же редкости не подходит.</li><li><b>Дополнительные материалы</b> — если они требуются для выбранного артефакта; состав и количество показаны в кузне.</li><li><b>Монеты</b> — сумма указана возле кнопки заточки.</li></ul><p>Для одного вида артефакта <b>цена и количество дополнительных материалов одинаковые на каждой ступени</b>. Например, переход с +0 на +1 и с +12 на +13 стоит одинаково. Для разных артефактов условия могут отличаться.</p>';
        $formula = $uk
            ? '<p>Кожен рівень заточування додає <b>5% від базового значення кожної власної характеристики артефакту</b>.</p><p style="text-align:center"><b>Значення = базова характеристика × (1 + рівень заточування × 0,05)</b></p><p>Бонус завжди рахується від базового значення, без послідовного перемноження. Наприклад, характеристика з базовим значенням 20 зміниться так:</p>'
            : '<p>Каждый уровень заточки добавляет <b>5% от базового значения каждой собственной характеристики артефакта</b>.</p><p style="text-align:center"><b>Значение = базовая характеристика × (1 + уровень заточки × 0,05)</b></p><p>Бонус всегда считается от базового значения, без последовательного перемножения. Например, характеристика с базовым значением 20 изменится так:</p>';
        $formula .= '<table class="coll brd2-all p10h p4v" cellspacing="0" cellpadding="0" style="margin:10px auto"><tbody><tr><th>'
            .($uk ? 'Заточування' : 'Заточка').'</th><th>Бонус</th><th>'
            .($uk ? 'Значення характеристики' : 'Значение характеристики').'</th></tr>';
        foreach ([0 => [0, 20], 1 => [5, 21], 5 => [25, 25], 10 => [50, 30], 20 => [100, 40]] as $level => [$bonus, $value]) {
            $formula .= '<tr><td align="center">+'.$level.'</td><td align="center">+'.$bonus.'%</td><td align="center"><b>'.$value.'</b></td></tr>';
        }
        $formula .= '</tbody></table>'.($uk
            ? '<p>Дробові прибавки також враховуються: базове значення 17 на +1 перетвориться на 17,85. Заточування посилює власні характеристики артефакту; окремі особливі ефекти не множаться автоматично.</p>'
            : '<p>Дробные прибавки тоже учитываются: базовое значение 17 на +1 превратится в 17,85. Заточка усиливает собственные характеристики артефакта; отдельные особые эффекты автоматически не умножаются.</p>');
        $steps = $uk
            ? '<ol><li>Покладіть у рюкзак артефакт, його копію +0 та всі необхідні матеріали. Підготуйте монети.</li><li>Прийдіть до кузні й відкрийте розділ «Заточування артефактів».</li><li>Перевірте схему: <b>артефакт + копія + матеріали → покращений артефакт</b>. Числа під компонентами означають «є / потрібно».</li><li>Перегляньте зміни характеристик унизу блока. Наведіть курсор на предмети, щоб відкрити підказки: результат показує характеристики наступного рівня.</li><li>Натисніть «Заточити». Копія +0, матеріали та монети витратяться, а вибраний артефакт отримає наступний рівень.</li></ol>'
            : '<ol><li>Положите в рюкзак артефакт, его копию +0 и все необходимые материалы. Подготовьте монеты.</li><li>Придите в кузню и откройте раздел «Заточка артефактов».</li><li>Проверьте схему: <b>артефакт + копия + материалы → улучшенный артефакт</b>. Числа под компонентами означают «есть / требуется».</li><li>Посмотрите изменения характеристик внизу блока. Наведите курсор на предметы, чтобы открыть подсказки: результат показывает характеристики следующего уровня.</li><li>Нажмите «Заточить». Копия +0, материалы и монеты израсходуются, а выбранный артефакт получит следующий уровень.</li></ol>';
        $important = $uk
            ? '<p><b>Артефакт для покращення зберігається.</b> Витрачається лише його копія +0, додаткові матеріали та монети. Заточена копія як компонент не підходить.</p><p>Одягнені предмети та предмети інших гравців не використовуються. Перед заточуванням завершіть відкриту угоду торгівлі.</p><p>Якщо кнопка недоступна, перевірте наявність копії +0, матеріалів і монет. Якщо артефакту немає в списку, переконайтеся, що він не одягнений і для нього доступне заточування.</p><p>Потрібен ще один артефакт? Читайте <a href="/library/sborka-artefaktov?category=artefakty"><b>«Збирання артефактів»</b></a>.</p>'
            : '<p><b>Улучшаемый артефакт сохраняется.</b> Расходуется только его копия +0, дополнительные материалы и монеты. Заточенная копия как компонент не подходит.</p><p>Надетые предметы и предметы других игроков не используются. Перед заточкой завершите открытую сделку торговли.</p><p>Если кнопка недоступна, проверьте наличие копии +0, материалов и монет. Если артефакта нет в списке, убедитесь, что он не надет и для него доступна заточка.</p><p>Нужен ещё один артефакт? Читайте <a href="/library/sborka-artefaktov?category=artefakty"><b>«Сборка артефактов»</b></a>.</p>';

        return $intro
            .$this->frame($uk ? 'Де заточувати артефакти' : 'Где точить артефакты', $where)
            .$this->frame($uk ? 'Що потрібно на один ступінь' : 'Что нужно на одну ступень', $resources)
            .$this->frame($uk ? 'Як зростають характеристики' : 'Как растут характеристики', $formula)
            .$this->frame($uk ? 'Порядок заточування' : 'Порядок заточки', $steps)
            .$this->frame($uk ? 'Важливі правила' : 'Важные правила', $important);
    }

    private function frame(string $title, string $body): string
    {
        return '<table class="library-game-frame" border="0" cellspacing="0" cellpadding="0"><tbody>'
            .'<tr height="22"><td width="20" class="tbl-shp-sml lt"><b></b></td><td class="tbl-shp-sml tt" align="center">'
            .'<table class="library-game-frame__title" border="0" cellspacing="0" cellpadding="0"><tbody><tr height="22">'
            .'<td width="27"><img src="/img/bg/info/tbl-usi_label-left.gif" width="27" height="22" alt=""></td>'
            .'<td class="tbl-usi_label-center" align="center">'.e($title).'</td>'
            .'<td width="27"><img src="/img/bg/info/tbl-usi_label-right.gif" width="27" height="22" alt=""></td></tr></tbody></table>'
            .'</td><td width="20" class="tbl-shp-sml rt"><b></b></td></tr>'
            .'<tr><td class="tbl-shp-sides ls">&nbsp;</td><td class="tbl-usi_bg" style="padding:8px 12px">'.$body.'</td><td class="tbl-shp-sides rs">&nbsp;</td></tr>'
            .'<tr height="18"><td width="20" class="tbl-shp-sml lb"><b></b></td><td class="tbl-shp-sml bb">&nbsp;</td><td width="20" class="tbl-shp-sml rb"><b></b></td></tr>'
            .'</tbody></table>';
    }
}
